{
  "findings": [
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instance should not have public IP",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance is launched in a public subnet but its public IP configuration is not explicitly set to false, potentially exposing it to the internet."
    },
    {
      "check_id": "AVD-AWS-0028",
      "title": "Instance does not require IMDS access to require a token",
      "resource": "aws_instance.web",
      "severity": "HIGH",
      "explanation": "The instance metadata service is not configured to require a token, allowing unrestricted access to instance metadata."
    },
    {
      "check_id": "CKV2_AWS_41",
      "title": "Ensure an IAM role is attached to EC2 instance",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance is not associated with an IAM instance profile, potentially limiting its ability to interact with other AWS services securely."
    }
  ],
  "patched_code": "resource "aws_instance" "web" {
  ami                    = "${var.ami}"
  instance_type          = "t2.micro"
  subnet_id              = "${aws_subnet.public-subnet.id}"
  vpc_security_group_ids = ["${aws_security_group.sgweb.id}"]
  associate_public_ip_address = false
  metadata_options {
    http_tokens = "required"
  }
  iam_instance_profile = "${aws_iam_instance_profile.web.name}"
}

resource "aws_iam_instance_profile" "web" {
  name = "web-instance-profile"
  role = "${aws_iam_role.web.name}"
}

resource "aws_iam_role" "web" {
  name        = "web-role"
  description = "Role for web instance"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })
}",
  "fix_summary": "Added associate_public_ip_address = false to prevent public IP assignment, enabled IMDS token requirement, and created an IAM instance profile and role for the EC2 instance."
}
